import type { ComponentType, ReactNode, SVGProps } from "react"

/**
 * Capy's own icon set, copied verbatim from capy.ai (24px grid, 2px strokes).
 * Capy does not use lucide: every glyph here is read from its inline SVGs. Use these
 * wherever a surface mirrors a Capy surface so icons never drift.
 */
export type CapyIconProps = SVGProps<SVGSVGElement> & { size?: number | string; strokeWidth?: number | string }
/** Anything that renders as an icon: Capy glyphs and (where Capy has no equivalent) lucide ones. */
export type IconComponent = ComponentType<CapyIconProps>

function make(name: string, children: ReactNode) {
  // Capy strokes are baked into the paths, so `strokeWidth` is accepted for lucide parity and ignored.
  const Icon = ({ className, size, strokeWidth: _strokeWidth, ...props }: CapyIconProps) => (
    <svg viewBox="0 0 24 24" fill="none" aria-hidden="true" width={size} height={size} className={className ?? (size === undefined ? "size-(--icon-sm)" : undefined)} {...props}>{children}</svg>
  )
  Icon.displayName = name
  return Icon
}
